  <script>
    const arabicMonths = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const today = new Date();
    let viewYear = today.getFullYear();
    let viewMonth = today.getMonth();
    let selectedDate = new Date(today);
    let selectedTime = "";

    const monthTitle = document.getElementById("monthTitle");
    const calendarDays = document.getElementById("calendarDays");
    const selectedDateLabel = document.getElementById("selectedDate");
    const confirmButton = document.getElementById("confirmButton");
    const toast = document.getElementById("toast");

    function sameDay(a, b) {
      return a.getFullYear() === b.getFullYear() &&
        a.getMonth() === b.getMonth() &&
        a.getDate() === b.getDate();
    }

    function updateDateLabel() {
      selectedDateLabel.textContent = `${selectedDate.getDate()} ${arabicMonths[selectedDate.getMonth()]}`;
    }

    function renderCalendar() {
      monthTitle.textContent = `${arabicMonths[viewMonth]} ${viewYear}`;
      calendarDays.innerHTML = "";

      const firstDay = new Date(viewYear, viewMonth, 1);
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const daysInPreviousMonth = new Date(viewYear, viewMonth, 0).getDate();

      // Saturday = 0
      const offset = (firstDay.getDay() + 1) % 7;

      for (let i = 0; i < offset; i++) {
        const empty = document.createElement("div");
        empty.className = "day empty";
        empty.setAttribute("role", "gridcell");
        calendarDays.appendChild(empty);
      }

      for (let day = 1; day <= daysInMonth; day++) {
        const button = document.createElement("button");
        const date = new Date(viewYear, viewMonth, day);
        button.type = "button";
        button.className = "day";
        button.textContent = day;
        button.setAttribute("role", "gridcell");
        button.setAttribute("aria-label", `${day} ${arabicMonths[viewMonth]}`);

        if (sameDay(date, today)) button.classList.add("today");
        if (sameDay(date, selectedDate)) button.classList.add("selected");
        if (date < new Date(today.getFullYear(), today.getMonth(), today.getDate())) {
          button.classList.add("unavailable");
          button.disabled = true;
        }

        button.addEventListener("click", () => {
          selectedDate = date;
          selectedTime = "";
          document.querySelectorAll(".slot").forEach(slot => {
            slot.classList.remove("selected");
          });
          confirmButton.disabled = true;
          updateDateLabel();
          renderCalendar();
        });

        calendarDays.appendChild(button);
      }
    }

    document.getElementById("prevMonth").addEventListener("click", () => {
      viewMonth--;
      if (viewMonth < 0) {
        viewMonth = 11;
        viewYear--;
      }
      renderCalendar();
    });

    document.getElementById("nextMonth").addEventListener("click", () => {
      viewMonth++;
      if (viewMonth > 11) {
        viewMonth = 0;
        viewYear++;
      }
      renderCalendar();
    });

    document.querySelectorAll(".slot").forEach(slot => {
      slot.addEventListener("click", () => {
        document.querySelectorAll(".slot").forEach(item => item.classList.remove("selected"));
        slot.classList.add("selected");
        selectedTime = slot.dataset.time;
        confirmButton.disabled = false;
      });
    });

    confirmButton.addEventListener("click", () => {
      if (!selectedTime) return;
      const time = selectedTime === "12:00" ? "12:00 ظهراً" : `${selectedTime.replace(":", ":")} صباحاً`;
      toast.textContent = `تم تأكيد موعدك يوم ${selectedDate.getDate()} ${arabicMonths[selectedDate.getMonth()]} الساعة ${time}`;
      toast.classList.add("show");
      setTimeout(() => toast.classList.remove("show"), 3500);
    });

    updateDateLabel();
    renderCalendar();
  </script>
